export const redirectUrl = (key: string) => {
  // const data = flatArr(menu);

  // 匹配旧 URL 格式时使用固定的 /yddoc 前缀（因为旧 URL 都是带这个前缀的）
  const url = `/yddoc${key}`;
  console.log(url, "访问url-=-=-=-==", decodeURI(url));
  const item = menu.find(
    (item) =>
      url.includes(item.path) ||
      decodeURI(url).toLowerCase().includes(item.path) ||
      (item.pathV2 && url.includes(item.pathV2))
  );
  if (item) {
    return item.newPath;
  } else {
    return "";
  }
};
